/**
 * A tool's `field_id` value → the TARGET aspect's field bag key. Shared by
 * `agent-tool`/`skill-tool` from-tf (neither owns the other, so this lives in
 * the cross-entity commons rather than either module). Three shapes: a
 * `resource-attr` to the field's own resource (custom fields, which have a
 * dedicated `elementum_<type>_field` block), a ref-only
 * `data.elementum_field` lookup on a recursively pulled target, or a `local.<aspect>_<key>_
 * field_id` reference (system fields - title/status/closedBy/…, which have
 * no resource of their own). Same recognition `automation/from-tf.ts`'s
 * `decodeValue` already does for record-path field refs.
 *
 * `scopeTfLabel`/`scope` identify the tool's RESOLVED target aspect (self,
 * or a foreign app/element per `target_id` — board issue #169), not always
 * the owning app: a field on a foreign aspect is scoped under that aspect's
 * own label, not the caller's.
 */
import type { FromTfContext } from "../../engine/pull/context.js";
import { type ChildResourceScope, type TfValue } from "../../engine/tf/index.js";
export declare function resolveToolFieldKey(fieldRef: TfValue | undefined, scopeTfLabel: string, scope?: ChildResourceScope, ctx?: Pick<FromTfContext, "dataAttrs" | "foreignFieldRefsByDataAddress">): string | undefined;
